import{_ as e,o as t,c as s,Q as a}from"./chunks/framework.b67c47e6.js";const i="/assets/upload-dialog.cfdf244a.svg",o="/assets/general-arrangement.61efca9c.svg",n="/assets/files-table.727fc005.svg",l="/assets/status-busy.43d6a74c.svg",r="/assets/status-uploaded.daff3642.svg",d="/assets/status-details.fa64fe12.svg",p="/assets/status-splitted.c413ad7b.svg",h="/assets/status-designs.50cf58ba.svg",c="/assets/status-splitting.32f6f958.svg",u="/assets/status-split-failed.f1ff1ea0.svg",g="/assets/operations-dialog.11da622c.svg",_=JSON.parse('{"title":"Files and Operations","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/projects/index.md","filePath":"tutorials/projects/index.md","lastUpdated":1790346505000}'),f={name:"tutorials/projects/index.md"},m=a('<h1 id="files-and-operations" tabindex="-1">Files and Operations <a class="header-anchor" href="#files-and-operations" aria-label="Permalink to &quot;Files and Operations&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#upload-files">Upload Files</a><ul><li><a href="#table-of-uploaded-files">Table of uploaded files</a></li></ul></li><li><a href="#operations">Operations</a><ul><li><a href="#split-full-ifc">Split full IFC</a></li><li><a href="#generate-designs">Generate Designs</a></li><li><a href="#detect-details">Detect details</a></li><li><a href="#analysis-prepare-the-viewer">Analysis (prepare the viewer)</a></li></ul></li></ul></nav><h2 id="upload-files" tabindex="-1">Upload Files <a class="header-anchor" href="#upload-files" aria-label="Permalink to &quot;Upload Files&quot;">​</a></h2><p>Files for each project are uploaded in <strong>Files &amp; Operations</strong>, in the project menu under <strong>Designs</strong>:</p><p>Click <strong>Upload</strong>. In the upload dialog, pick a <strong>file group</strong> first, and optionally a <strong>tipo</strong>, then drop, paste or browse the files and click <strong>Upload</strong>. The file group tells the system what the file is, and you choose it yourself. It starts on <strong>Assembly drawings (.pdf)</strong>.</p><p><img src="'+i+'" alt="The upload dialog"></p><ol><li>The file group: what the files are. Pick it before you add the files.</li><li>Drop, paste or browse the files. All of them get the group you picked.</li></ol><p>The file groups are:</p><ul><li><strong>Assembly Files</strong>: Assembly IFCs (.ifc), Extra Assembly IFCs (.ifc), Assembly drawings (.pdf), Machine Files (.jjs, .wup, .btl).</li><li><strong>Module Files</strong>: Module IFCs (.ifc), Extra Module IFCs (.ifc), Module drawings (.pdf).</li><li><strong>Project Files</strong>: Project IFCs (.ifc), External IFCs (.ifc), Project drawings (.pdf).</li><li><strong>Details and documentation</strong>: Details (.pdf), Documentation (.pdf, .jpeg, .png), Specifications (.pdf, text). Documentation and specifications can also be added as text with the <strong>Add as text</strong> switch.</li></ul><p>The file name decides which design a file belongs to:</p><ul><li><p>IFCs: used for the 3D viewer, BoMs and machine files. The system reads them with the project&#39;s IFC Parsing Setup. The file name without extension is the design name. Example: &quot;PNL30-25.ifc&quot; belongs to design &quot;PNL30-25&quot;.</p></li><li><p>Extra IFCs: the design name is the part before the first &quot; - &quot;. Example: &quot;PNL30-25 - Installations.ifc&quot;.</p></li><li><p>Machine files: the file name without extension is the design name. Example: &quot;PNL30-25.btl&quot;.</p></li></ul><div class="info custom-block"><p class="custom-block-title">Full Project IFCs</p><p>You can also upload full project IFCs and the system can split them into one IFC per design. Upload them in the <strong>Project IFCs (.ifc)</strong> group. The file name does not matter. Example: &quot;OlaraAvenue15.ifc&quot;.</p></div><ul><li><p>Drawings: .pdf file format. They are shown in the viewer. Drawing file names must follow the format &quot;Merk DESIGN_NAME - DRAWING_NUMBER - DRAWING_NAME.pdf&quot;. The word &quot;Merk&quot; at the start is optional. Example: &quot;Merk PNL30-25 - 1 - Zone 0 MAIN VIEW.pdf&quot;. If a drawing name does not follow this format, the upload shows a warning.</p></li><li><p>Details and documentation: .pdf file format. Also shown in the viewer. The file name without extension is the detail name that the system looks for in drawings. Example: &quot;V-12.pdf&quot;. Documentation files are linked to every design of the project.</p></li></ul><div class="info custom-block"><p class="custom-block-title">Full Project PDFs</p><p>In design mode, the viewer shows a &quot;General Arrangement&quot; entry at the top of the list. It opens the full project IFCs in 3D and the drawings uploaded as <strong>Project drawings (.pdf)</strong>, one button per drawing.</p><p><img src="'+o+'" alt="The viewer in design mode, on the General Arrangement"></p><ol><li>The list filter set to <strong>Design</strong>.</li><li>The <strong>General Arrangement</strong> entry.</li><li>The designs, with their revisions. Older revisions are red.</li><li><strong>3D</strong> and one button per project drawing.</li></ol></div><h3 id="table-of-uploaded-files" tabindex="-1">Table of uploaded files <a class="header-anchor" href="#table-of-uploaded-files" aria-label="Permalink to &quot;Table of uploaded files&quot;">​</a></h3><p>The table of files is shown below the upload summary. The summary counts the files, how many are linked to a design and how many name a design that does not exist, and shows the project&#39;s parsing setup with a link to change it.</p><p><img src="'+n+'" alt="The Files &amp; Operations view"></p><ol><li><strong>Upload</strong> and <strong>Operations</strong>.</li><li>The summary: files, files linked to a design, and files that name a design that does not exist.</li><li>The search and <strong>Only latest versions</strong>.</li><li>The design of each file. A full IFC shows how many designs came out of it; an orange chip names a design that does not exist.</li><li>The status tags, explained below.</li></ol><p>Use <strong>Filename search</strong> to filter the table, and <strong>Only latest versions</strong> to hide older versions of files uploaded again with the same name. Select rows to delete, download or split several files at once. The <strong>Design</strong> column shows the design each file is linked to.</p><p>Each status tag has its purpose:</p><table><thead><tr><th>Tag</th><th>Description</th></tr></thead><tbody><tr><td><img src="'+l+'" alt="busy"></td><td>File is busy. An ongoing operation locked this file. It is unlocked when the operation ends. Files are also unlocked when you use <strong>Clean stucked jobs</strong> in the operations menu. A big operation can run for more than 1 hour.</td></tr><tr><td><img src="'+r+'" alt="uploaded"></td><td>This file has been successfully uploaded, and it can now be used in operations.</td></tr><tr><td><img src="'+d+'" alt="details"></td><td>This file has already been scanned for details. It can be an IFC, a drawing, or a detail.</td></tr><tr><td><img src="'+p+'" alt="splitted"></td><td>This full IFC file has already been split. The tag reads &quot;splitted&quot;.</td></tr><tr><td><img src="'+h+'" alt="designs"></td><td>This file was already used in the design generation operation. If it is the newest version of its design, it is attached to the design.</td></tr><tr><td><img src="'+c+'" alt="splitting 45%"></td><td>The file is being split with <strong>Split selected files</strong>. The percentage updates while the split runs.</td></tr><tr><td><img src="'+u+'" alt="split failed"></td><td>The split started with <strong>Split selected files</strong> failed for this file.</td></tr></tbody></table><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><p>Once project files are uploaded, click <strong>Operations</strong> to open the project operations dialog. Each operation shows its last run and status, and has its own <strong>Launch</strong> button. <strong>Launch all</strong> runs Split, Generate designs and Detect details one after the other. The menu at the top right of the dialog has <strong>Clean stucked jobs</strong>, which marks unfinished operations as failed and unlocks busy files. Use it only when you are sure no operation is still running.</p><p><img src="'+g+'" alt="The project operations dialog"></p><ol><li>The menu with <strong>Clean stucked jobs</strong>.</li><li><a href="#split-full-ifc">Split full IFC</a>.</li><li><a href="#generate-designs">Generate Designs</a>.</li><li><a href="#detect-details">Detect details</a>.</li></ol><h3 id="split-full-ifc" tabindex="-1">Split full IFC <a class="header-anchor" href="#split-full-ifc" aria-label="Permalink to &quot;Split full IFC&quot;">​</a></h3><p>Full IFCs are split into one assembly IFC per design. The new files are added to the project as Assembly IFCs and can be downloaded. The split also stores the quantity of each design and the phases and batches found in the IFC, so they are available in Production Counts. How assemblies are found in the IFC depends on the IFC Parsing Setup.</p><p>The split is available when the IFC splitter module is enabled for your company.</p><div class="warning custom-block"><p class="custom-block-title">Designs</p><p>Split full IFC will not create &quot;designs&quot;. Run Generate designs afterwards.</p></div><div class="tip custom-block"><p class="custom-block-title">Parameters</p><p>☑️ <strong>Split project .ifc&#39;s into assembly .ifc&#39;s</strong> Splits the files uploaded as Project IFCs.</p><p>☑️ <strong>Split module .ifc&#39;s into assembly .ifc&#39;s</strong> Splits the files uploaded as Module IFCs.</p><p>☑️ <strong>Resplit already splitted files</strong> Also splits files that were already split. Normally you don&#39;t check this.</p><p>☑️ <strong>Skip standard library design names</strong> Does not create IFCs for designs that already exist in the standard library.</p></div><p>If no file group is checked, the split does nothing.</p><p>You can also select Project, Module or External IFCs in the table and click <strong>Split selected files</strong>. This opens <strong>Split into hierarchy</strong>, a newer splitting engine (beta) that can split into modules, assemblies in modules and assemblies at project root.</p><h3 id="generate-designs" tabindex="-1">Generate Designs <a class="header-anchor" href="#generate-designs" aria-label="Permalink to &quot;Generate Designs&quot;">​</a></h3><p>The system collects the IFCs, drawings and machine files of the project and creates &quot;design&quot; objects.</p><ul><li><p>A list of design names is built from the file names of assembly and module IFCs, drawings and machine files.</p></li><li><p>Each file is attached to its design. All the documentation files are linked to every design, so they are always available.</p></li><li><p>When a design gets new files, it gets a new revision.</p></li></ul><div class="tip custom-block"><p class="custom-block-title">Parameters</p><p>☑️ <strong>Keep current revision numbers</strong> Designs do not get a new revision number, even if new files were uploaded.</p><p>☑️ <strong>Generate elements in phase/batch</strong> Creates one unit of each new or changed design in the phase and batch you enter. Left empty, they are &quot;Phase_1&quot; and &quot;Batch_1&quot;.</p><p>☑️ <strong>Generate drawings from IFC</strong> Generates drawings from the IFC of each design, with the default set of views.</p></div><h3 id="detect-details" tabindex="-1">Detect details <a class="header-anchor" href="#detect-details" aria-label="Permalink to &quot;Detect details&quot;">​</a></h3><p>Details can be automatically detected in IFCs and PDF drawings. Found detail names are linked to the design and then shown in the viewer.</p><div class="tip custom-block"><p class="custom-block-title">Parameters</p><p>☑️ <strong>Scan IFC files</strong> IFCs are scanned for detail names in the property &quot;DET_NUMBER&quot;. Found names are linked to the design.</p><p>☑️ <strong>Scan PDF files</strong> Drawings are scanned to find detail and specification names, and details are scanned to find specification names. Found names are linked to the design. This option is checked by default.</p></div><p>If your detail names can&#39;t be detected by the system, you may have a rasterized export, or a rasterized font in a vectorized export, such as the <a href="https://www.autodesk.com/support/technical/article/caas/sfdcarticles/sfdcarticles/How-to-create-selectable-and-searchable-text-in-a-PDF-from-AutoCAD.html" target="_blank" rel="noreferrer">well known issue with AutoCad</a>.</p><h3 id="analysis-prepare-the-viewer" tabindex="-1">Analysis (prepare the viewer) <a class="header-anchor" href="#analysis-prepare-the-viewer" aria-label="Permalink to &quot;Analysis (prepare the viewer)&quot;">​</a></h3><p>The analysis starts automatically when a design gets a new IFC, for example after Generate designs. There is no button for it in the operations dialog. If the company setting <strong>Launch analysis automatically</strong> is off, or you need to run it again, select the designs in <strong>Designs</strong> and click <strong>Force analysis</strong>. The <strong>Analysis</strong> column of the designs table shows the status of each design.</p><div class="warning custom-block"><p class="custom-block-title">Slow task!</p><p>⚠️ This operation takes time. It runs many heavy computations and database tasks.</p></div><ul><li><p>IFC geometry is analyzed to find the rotation and translation matrices (orientation of the panel in the world coordinate system).</p></li><li><p>Panel size and bruto/neto areas are also calculated here. So if you use bruto areas in Production Counts, you need to wait for this operation.</p></li><li><p>Each part of the IFC is analyzed, generating drawings and metadata which are saved in the database. This gives fast access to the information when the user clicks on a part in the 3D viewer.</p></li><li><p>Drawings are only generated for wood and plate parts, and for parts in custom branches marked for logistics in the IFC Parsing Setup. So, if your IFC Parsing Setup is incomplete, some part drawings may be missing.</p></li></ul>',44),w=[m];function b(y,F,v,k,I,C){return t(),s("div",null,w)}const q=e(f,[["render",b]]);export{_ as __pageData,q as default};
